BEGIN;
CREATE TABLE invoices (id uuid PRIMARY KEY,trade_id uuid NOT NULL,invoice_kind text NOT NULL CHECK(invoice_kind='BROKERAGE_SERVICE'),gross numeric NOT NULL CHECK(gross>0),net numeric NOT NULL CHECK(net>=0),tax numeric NOT NULL CHECK(tax>=0),currency char(3) NOT NULL,tax_policy_version text NOT NULL,material_invoice boolean NOT NULL DEFAULT false CHECK(material_invoice=false),created_at timestamptz NOT NULL);
CREATE TABLE ledger_transactions (id uuid PRIMARY KEY,idempotency_key text NOT NULL UNIQUE,trade_id uuid NOT NULL,event_type text NOT NULL,occurred_at timestamptz NOT NULL,reverses_transaction_id uuid REFERENCES ledger_transactions(id));
CREATE TABLE ledger_entries (id uuid PRIMARY KEY,transaction_id uuid NOT NULL REFERENCES ledger_transactions(id),account_code text NOT NULL CHECK(account_code IN ('BROKERAGE_RECEIVABLE','BROKERAGE_REVENUE','GST_TAX_LIABILITY','SABLESTONE_BANK_CASH','PROVIDER_FEE_EXPENSE','SUSPENSE','FX_GAIN_LOSS')),direction text NOT NULL CHECK(direction IN ('DEBIT','CREDIT')),amount numeric NOT NULL CHECK(amount>=0),currency char(3) NOT NULL,external_reference text NOT NULL);
CREATE TABLE reconciliation_results (trade_id uuid PRIMARY KEY,state text NOT NULL CHECK(state IN ('PROVIDER_ONLY','BANK_PARTIAL','RECONCILED','MISMATCH')),expected numeric NOT NULL,provider_disbursed numeric,bank_received numeric,provider_reference text,bank_reference text,evaluated_at timestamptz NOT NULL);
CREATE TRIGGER ledger_transactions_no_update_delete BEFORE UPDATE OR DELETE ON ledger_transactions FOR EACH ROW EXECUTE FUNCTION reject_domain_event_mutation();
CREATE TRIGGER ledger_entries_no_update_delete BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION reject_domain_event_mutation();
INSERT INTO schema_migrations(version) VALUES('0021_ledger');COMMIT;
